-- Step 6d: refresh denormalised parent EN/TH on child rows
UPDATE public.address_th_district AS d
SET province_name_en = p.province_name_en,
    province_name_th = p.province_name_th
FROM public.address_th_province AS p
WHERE d.province_id = p.id::bigint AND p.id = '11';
UPDATE public.address_th_subdistrict AS s
SET district_name_en = d.district_name_en,
    district_name_th = d.district_name_th
FROM public.address_th_district AS d
WHERE s.district_id = d.id::bigint
  AND d.id IN ('1027', '1029', '1037', '1049', '1913', '2409', '3029', '3032', '3117', '3123', '3410', '4106', '4705', '4904', '5025', '5402', '5515', '5602', '5603', '5604', '5605', '5606', '5607', '5608', '5609', '6010', '6014', '7201', '8023', '8419', '8503', '9001', '9603');
UPDATE public.address_th_subdistrict AS s
SET district_name_en = d.district_name_en,
    district_name_th = d.district_name_th
FROM public.address_th_district AS d
WHERE s.district_id = d.id::bigint AND d.id = '4029';
